// DEMO DATA, for local development only. Names, prices and colours are placeholders that
// describe the supplied photos; they are not real Hestola products or prices.
// Replace with the catalogue API once the backend exists (design.md §18).
// Prices are integer paise (design.md §17).
//
// `images` are cut-outs generated by scripts/cut-out-product-images.py into public/products/.
// Without `back`, the rail reuses the front; without `side`, it turns the front away.

const photo = (slug, views) =>
  Object.fromEntries(views.map((view) => [view, `/products/${slug}/${view}.webp`]))

const VIEWS = ['front', 'back', 'side']

// Demo sizes with stock per size, so the product sheet can show sold-out and low-stock states.
// Not a Hestola size chart: real sizes and stock come from admin data per variant (§17).
const sizes = (stock) => ['XS', 'S', 'M', 'L', 'XL', 'XXL'].map((label, i) => ({ label, stock: stock[i] }))

